SELECT p.sku, p.product_name 
FROM store.products p 
WHERE p.pack_size = '5 kg' AND p.product_name ILIKE '%atta%';

SELECT column_name 
FROM information_schema.columns 
WHERE table_schema = 'store' AND table_name = 'products';

SELECT column_name 
FROM information_schema.columns 
WHERE table_schema = 'store' AND table_name = 'pos_lines';

SELECT column_name 
FROM information_schema.columns 
WHERE table_schema = 'store' AND table_name = 'shelf_audits';

SELECT 
    (SELECT COUNT(DISTINCT audit_ts) FROM store.shelf_audits sa JOIN store.products p ON sa.sku = p.sku WHERE p.pack = '5 kg' AND p.name ILIKE '%atta%' AND sa.audit_ts >= '2026-06-01' AND sa.audit_ts < '2026-07-01' AND sa.status = 'on shelf')::float / 
    NULLIF((SELECT COUNT(DISTINCT audit_ts) FROM store.shelf_audits sa JOIN store.products p ON sa.sku = p.sku WHERE p.pack = '5 kg' AND p.name ILIKE '%atta%' AND sa.audit_ts >= '2026-06-01' AND sa.audit_ts < '2026-07-01'), 0) as osa;

SELECT 
    (SELECT COUNT(DISTINCT audit_ts) FROM store.shelf_audits sa JOIN store.products p ON sa.sku = p.sku WHERE p.pack = '5 kg' AND p.name ILIKE '%atta%' AND sa.audit_ts >= '2026-06-01' AND sa.audit_ts < '2026-07-01' AND sa.status = 'empty') as empty_count,
    (SELECT price_inr FROM store.products p WHERE p.pack = '5 kg' AND p.name ILIKE '%atta%' LIMIT 1) as price;
